INSERT OR REPLACE INTO prompt_blueprints (id, project, category, raw_user_prompt, context, target_stack, why_it_failed_before, key_upgrades) VALUES ('learned-mobile-qa', 'Mobile Web App', 'ui-testing', 'verify mobile responsive layout and touch interactions for soft keyboard expansion', 'Next.js 16 + Tailwind responsive web app with mobile-first viewport and navigation drawers.', 'Playwright (Mobile Viewport Emulation)', 'AI wrote generic desktop tests with full-screen coordinates, ignoring touch targets, virtual keyboard occlusion, viewport clipping, and dynamic orientation changes.', '["Emulate mobile devices (iPhone 14 / Pixel 7 viewports)","Touch target size assertions (minimum 44x44px per WCAG)","Keyboard popup viewport shrink simulation","Drawer and navigation bar touch gestures","No hardcoded click coordinates"]');
INSERT OR REPLACE INTO prompt_blueprints (id, project, category, raw_user_prompt, context, target_stack, why_it_failed_before, key_upgrades) VALUES ('learned-card-layout-diff', 'Healthcare Portal', 'ui-testing', 'doctor profile cards have different vertical alignments between desktop and mobile', 'Healthcare directory portal doctor cards rendering inconsistently across desktop and mobile browsers.', 'Playwright + Visual Regression / CSS Audit', 'AI guessed without inspecting CSS flexbox/grid wrapper properties, break-inside properties, and image aspect-ratio discrepancies.', '["CSS Grid vs Flexbox alignment inspection criteria","Visual screenshot regression testing with maxDiffPixels threshold","Card content overflow and variable length bio fields","Multi-device responsive breakpoint verification (sm, md, lg)"]');
INSERT OR REPLACE INTO prompt_blueprints (id, project, category, raw_user_prompt, context, target_stack, why_it_failed_before, key_upgrades) VALUES ('learned-chatbot-appointment', 'Clinical Triage Assistant', 'healthcare-doctor', 'test the conversational patient triage widget on landing page and verify appointment slot booking flow', 'Interactive virtual doctor triage widget that guides patient through symptoms and books slot.', 'Playwright E2E + Mock Triage API', 'AI generated a standard click test that skipped conversational state machine verification, slot conflict edge cases, and medical disclaimer requirements.', '["Multi-turn conversational state machine assertions","Calendar slot reservation & double-booking race condition checks","HIPAA/patient privacy consent checkbox validation","Network mocking of backend triage endpoint (/api/v1/doctor/triage)"]');
INSERT OR REPLACE INTO prompt_blueprints (id, project, category, raw_user_prompt, context, target_stack, why_it_failed_before, key_upgrades) VALUES ('learned-betterstack-dns', 'Cloud SRE & DNS Monitor', 'devops-infra', 'diagnose dns lookup failure and configure heartbeat uptime probes with cloudflare proxy awareness', 'Uptime heartbeat alerts failing due to Cloudflare DNS resolution and edge proxy caching.', 'Cloudflare DNS + Better Stack Heartbeat Script', 'AI answered "check your internet" instead of diagnosing Cloudflare Proxy (orange vs grey cloud), DNS CNAME flattening, SSL edge certs, and TTL propagation.', '["DNS diagnostic procedure (dig +trace, nslookup, WHOIS)","Cloudflare Proxied vs DNS-Only (Grey Cloud) toggle check for uptime pings","Better Stack HTTP status vs TCP/ICMP ping configuration","Automated fallback endpoint & alert webhook notifications"]');
INSERT OR REPLACE INTO prompt_blueprints (id, project, category, raw_user_prompt, context, target_stack, why_it_failed_before, key_upgrades) VALUES ('learned-upstash-redis-inactivity', 'Distributed Cache & Keep-Alive', 'devops-infra', 'configure automated lightweight keep-alive heartbeat worker to prevent free-tier cloud cache from sleeping during low traffic', 'Free-tier Upstash Redis or cloud containers sleeping after periods of inactivity, dropping chat sessions.', 'Node.js / Cloudflare Worker Cron + Better Stack', 'AI suggested paying for enterprise Redis rather than creating an automated lightweight ping/keep-alive cron worker.', '["Zero-cost automated keep-alive cron job (every 10 minutes)","Exponential backoff reconnection logic on Redis client error","Better Stack health check integration for Redis REST ping","Graceful degradation when Redis wakes up from cold start"]');
INSERT OR REPLACE INTO prompt_blueprints (id, project, category, raw_user_prompt, context, target_stack, why_it_failed_before, key_upgrades) VALUES ('learned-free-tier-deployment', 'Ephemeral Messaging Service', 'devops-infra', 'deploy ephemeral websocket application on zero-cost cloud tier with in-memory TTL purge', 'Deploying real-time WebSockets & ephemeral chat on zero-cost infrastructure.', 'Render Free Tier + Cloudflare DNS / Pages', 'AI recommended expensive AWS ECS / ALB setups that cost $50+/month.', '["Zero-cost architecture (Render Web Service + Cloudflare DNS CNAME)","Handling Render 15-minute sleep with client-side reconnection banners","In-memory RingBuffer / Map with automatic TTL expiry to stay within RAM limits","Web-first deployment checklist with custom domain SSL"]');
INSERT OR REPLACE INTO prompt_blueprints (id, project, category, raw_user_prompt, context, target_stack, why_it_failed_before, key_upgrades) VALUES ('learned-security-privacy-expert', 'WebRTC & WebSocket Platform', 'security-privacy', 'perform comprehensive security and privacy audit on websocket rooms and webrtc peer signaling', 'Ephemeral chat with room passcodes, media streaming, and host door knock approval.', 'OWASP / WebRTC / Socket.io Security Review', 'AI listed generic Wikipedia summaries of XSS rather than pinpointing code-level vulnerabilities in WebSockets, room traversal, and token forgery.', '["Socket.io room authorization & unauthorized broadcast prevention","XSS sanitization in markdown & plain text message payloads","Timing-attack safe passcode comparison (crypto.timingSafeEqual)","Rate limiting & DDoS protection per IP on socket connection","Ephemeral memory wipe verification (zero traces on disk/logs)"]');
INSERT OR REPLACE INTO prompt_blueprints (id, project, category, raw_user_prompt, context, target_stack, why_it_failed_before, key_upgrades) VALUES ('learned-zero-trace-burn', 'Ephemeral Messaging Service', 'security-privacy', 'implement zero-trace ephemeral chat where shared images and messages auto-burn after 10 seconds', '10-second auto-burn photo & text countdown, host approval doorway.', 'Client-side Decryption + In-Memory Auto-Purge', 'AI suggested storing images on AWS S3, violating the zero-trace, no-storage requirement.', '["In-memory ArrayBuffer storage with strict setTimeout purge","Client-side Canvas rendering with disabled right-click and copy","Client countdown timer synchronization with server-authoritative burn signal","Prevent browser disk caching via Cache-Control: no-store, private"]');
INSERT OR REPLACE INTO prompt_blueprints (id, project, category, raw_user_prompt, context, target_stack, why_it_failed_before, key_upgrades) VALUES ('learned-infisical-secrets', 'Secrets & Environment Management', 'secrets-observability', 'sync production secrets and environment variables from secret vault to cloud hosting services via cli', 'Syncing secrets across dev/prod environments and deploying via Infisical CLI.', 'Infisical CLI + Render API + Cloudflare Tokens', 'AI assumed hardcoded .env files and leaked instructions for manual copy-pasting rather than programmatic Infisical CLI commands.', '["Infisical CLI programmatic command scripts (infisical export / run)","Strict environment scoping (dev vs prod vs local)","Automated push to Render environment variables via Render API","Zero secrets in git or build logs verification"]');
INSERT OR REPLACE INTO prompt_blueprints (id, project, category, raw_user_prompt, context, target_stack, why_it_failed_before, key_upgrades) VALUES ('learned-sentry-integration', 'Production Observability Suite', 'secrets-observability', 'configure production sentry observability with sourcemap uploads, pii scrubbing, and automated ci secret injection', 'End-to-end production error tracking and performance monitoring for Next.js.', 'Sentry Next.js SDK + Infisical SENTRY_AUTH_TOKEN', 'AI omitted source map upload configuration and PII sanitization in error breadcrumbs.', '["Complete next.config.ts withSentryConfig wrapper","Client, server, and edge runtime Sentry init files","Automatic PII stripping (scrubbing user passwords, tokens, chat texts)","Infisical Sentry auth token injection during CI build"]');
INSERT OR REPLACE INTO prompt_blueprints (id, project, category, raw_user_prompt, context, target_stack, why_it_failed_before, key_upgrades) VALUES ('learned-scale-n-users', 'High-Concurrency Cluster Platform', 'concurrency-scaling', 'how we are going to deal with n number of session and how we can deal with n user in a session?', 'Real-time WebSocket server handling concurrent chat rooms and live candidate interviews.', 'Socket.io Cluster + Redis Adapter + Memory Profiling', 'AI gave vague answers about load balancers without explaining sticky sessions, Socket.io Redis adapter, and socket memory footprint.', '["Socket.io Redis Streams / Redis Adapter architecture","Sticky session cookie configuration for reverse proxy (Nginx / Cloudflare)","Socket connection heartbeat and zombie client cleanup timeout","Memory footprint calculation per connected client (~15KB/socket)"]');
INSERT OR REPLACE INTO prompt_blueprints (id, project, category, raw_user_prompt, context, target_stack, why_it_failed_before, key_upgrades) VALUES ('learned-terrace-farming-prompts', 'Technical Infographic Generator', 'image-generation', 'generate high-detail photorealistic prompt specifications for urban terrace agriculture with soil formulas and crop timelines', 'Generating hyper-detailed infographic visual prompts for agricultural terrace gardening.', 'Structured Prompt Generator (Hindi + English) + Midjourney / Imagen', 'AI generated generic stock photo descriptions with no crop timing, Hindi steps, soil ratios, or realistic rooftop terrace details.', '["Bilingual content specification (Hindi steps + English visual prompt)","Exact potting soil ratio formulas (40% loam + 30% vermicompost + 20% cocopeat + 10% sand)","Photorealistic prompt keywords (morning dew, terracotta pots, 8K, authentic rooftop garden)","Crop timeline, germination days, and harvest cycles table"]');
INSERT OR REPLACE INTO prompt_blueprints (id, project, category, raw_user_prompt, context, target_stack, why_it_failed_before, key_upgrades) VALUES ('learned-interview-portal-video', 'Live Video & Coding Platform', 'webrtc-video', 'candidate video is freezing during live technical interview fix audio video desync', 'Live candidate coding interview with simultaneous Monaco editor, screen sharing, and WebRTC video.', 'WebRTC SimplePeer + Socket.io Signaling', 'AI guessed random timeouts instead of configuring STUN/TURN fallback relays, checking renegotiation state, and monitoring packet loss.', '["STUN/TURN fallback credentials for symmetric NAT networks","Dynamic bitrate adaptation via RTCRtpSender","Independent signaling socket reconnection without dropping active media streams"]');
INSERT OR REPLACE INTO prompt_blueprints (id, project, category, raw_user_prompt, context, target_stack, why_it_failed_before, key_upgrades) VALUES ('learned-document-ai-pdf', 'Enterprise IP & Patent Compliance', 'patent-compliance', 'audit our architecture against technical patent claims and verify commercial open-source license compliance', 'System architecture alignment and patent claim verification pipeline.', 'Patent Compliance Matrix + pdfplumber', 'AI gave a conversational summary without building a paragraph-to-module traceability matrix or checking copyleft dependencies.', '["Patent claim-to-code traceability matrix","Copyleft license audit (banning GPL/AGPL from commercial release)","Clean-room independent invention documentation"]');
INSERT OR REPLACE INTO prompt_blueprints (id, project, category, raw_user_prompt, context, target_stack, why_it_failed_before, key_upgrades) VALUES ('learned-floci-local-aws', 'Local Cloud Emulation (FinOps)', 'local-cloud-emulation', 'can we use https://github.com/floci-io/floci for aws for local to avoid paying any cloud bills', 'Local cloud emulation for testing S3 uploads and DynamoDB without incurring AWS expenses.', 'Floci Local AWS + Docker Compose', 'AI suggested deploying directly to AWS rather than configuring a zero-cost local Floci container with endpoint overrides.', '["Docker Compose Floci / LocalStack orchestration","AWS SDK v3 custom endpoint URL override (http://localhost:4566)","Automated local bucket provisioning script on startup"]');
INSERT OR REPLACE INTO prompt_blueprints (id, project, category, raw_user_prompt, context, target_stack, why_it_failed_before, key_upgrades) VALUES ('learned-patient-cache-sync', 'Realtime Dashboard & State Sync', 'state-cache-invalidation', 'fix stale cache issue where newly created patient records do not appear without a full page reload', 'Doctor and reception dashboard after adding a new patient.', 'TanStack Query (React Query) Cache Invalidation', 'AI told user to press F5 instead of fixing React Query mutation cache invalidation and write-after-read replication lag.', '["queryClient.invalidateQueries matching exact query key tags","Optimistic UI state updates for immediate table insertion","Write-after-read consistency handling"]');
INSERT OR REPLACE INTO prompt_blueprints (id, project, category, raw_user_prompt, context, target_stack, why_it_failed_before, key_upgrades) VALUES ('learned-landing-branch-split', 'Enterprise Monorepo Separation', 'monorepo-branch-split', 'separate public landing page from authenticated staff portal into isolated monorepo packages', 'Separating customer-facing public landing page from internal authenticated staff portal.', 'Turborepo Apps Separation (Landing vs Staff)', 'AI mixed staff portal components and admin routes into the public landing page repository.', '["Strict package boundary isolation: apps/landing (public) vs apps/portal (internal)","Ensuring public web bundle has zero staff credentials or private API routes","Shared UI design system package with peer-dependency deduplication"]');
INSERT OR REPLACE INTO prompt_blueprints (id, project, category, raw_user_prompt, context, target_stack, why_it_failed_before, key_upgrades) VALUES ('learned-social-automation', 'Automated Social Publisher', 'social-automation', 'schedule linkedin post with image and handle oauth token refresh automatically in background', 'Scheduled social publishing with OAuth 2.0 PKCE and media uploads.', 'LinkedIn REST API + BullMQ + Node.js', 'AI wrote code that failed as soon as the 60-day access token expired because it lacked background refresh rotation.', '["Proactive OAuth 2.0 token refresh rotation before expiration","Exponential backoff rate-limit retry respecting platform headers","Chunked resumable media upload protocol"]');
INSERT OR REPLACE INTO prompt_blueprints (id, project, category, raw_user_prompt, context, target_stack, why_it_failed_before, key_upgrades) VALUES ('learned-terrace-farming-iot', 'Smart Agriculture IoT Platform', 'iot-terrace-farming', 'smart irrigation rule based on soil moisture sensor readings and rain forecast to avoid overwatering', 'ESP32 IoT soil moisture sensor controlling terrace irrigation valve with OpenWeatherMap forecast.', 'MQTT Telemetry + Weather API Rule Engine', 'AI wrote an unconditional threshold trigger that watered plants even during torrential rain.', '["Weather forecast precipitation suppression (>60% rain probability delay)","Exact potting soil ratio formulas for urban terrace containers","MQTT QoS 1 message persistence for Wi-Fi reconnection recovery"]');